<style>
:root{--app-bg:#F6F9FF;--sidebar-bg:#EAF2FF;--sidebar-active-bg:#DCEBFF;--sidebar-active-text:#0B4DBA;--sidebar-text:#334155;--topbar-bg:#FFFFFF;--card-bg:#FFFFFF;--primary:#0B63F6;--primary-hover:#084FC7;--text-main:#0F172A;--text-muted:#64748B;--border:#D8E2F0;--soft-border:#E6EEF8;--success-bg:#EAF8F0;--success-text:#15803D;--warning-bg:#FFF7E6;--warning-text:#B45309;--danger-bg:#FEECEC;--danger-text:#B91C1C;--info-bg:#EEF6FF;--info-text:#0B4DBA;--shadow:0 8px 24px rgba(15,23,42,.04)}
*{box-sizing:border-box}.mess-ui-body{margin:0;background:var(--app-bg);color:var(--text-main);font-family:Inter,ui-sans-serif,system-ui,-apple-system,Segoe UI,sans-serif;font-size:14px;line-height:1.45}.mess-ui-link{text-decoration:none;color:inherit}.mess-ui-icon{font-family:'Material Symbols Outlined';font-size:20px;line-height:1;font-variation-settings:'FILL' 0,'wght' 450,'GRAD' 0,'opsz' 22}.mess-ui-shell{min-height:100vh;display:grid;grid-template-columns:280px minmax(0,1fr)}.mess-ui-sidebar{position:sticky;top:0;height:100vh;overflow:auto;background:var(--sidebar-bg);padding:22px 16px;border-right:1px solid var(--soft-border)}.mess-ui-brand{display:flex;align-items:center;gap:12px;padding:4px 8px 22px}.mess-ui-logo{width:44px;height:44px;border-radius:14px;background:#fff;border:1px solid var(--soft-border);display:grid;place-items:center;color:var(--primary);font-weight:800;font-size:20px}.mess-ui-brand-title{font-weight:800;font-size:17px;letter-spacing:-.02em}.mess-ui-brand-sub{font-size:12px;color:var(--text-muted);font-weight:600;margin-top:2px}.mess-ui-nav-label{font-size:11px;color:#7890ad;font-weight:800;text-transform:uppercase;letter-spacing:.08em;padding:12px 12px 8px}.mess-ui-nav-item{display:flex;align-items:center;gap:11px;padding:10px 12px;margin:3px 0;border-radius:999px;color:var(--sidebar-text);font-weight:650}.mess-ui-nav-item:hover,.mess-ui-nav-item.is-active{background:var(--sidebar-active-bg);color:var(--sidebar-active-text)}.mess-ui-topbar{height:72px;background:var(--topbar-bg);border-bottom:1px solid var(--soft-border);display:flex;align-items:center;justify-content:space-between;padding:0 28px;position:sticky;top:0;z-index:5}.mess-ui-search{width:min(470px,42vw);height:42px;border:1px solid var(--soft-border);border-radius:999px;background:#FBFDFF;color:var(--text-muted);display:flex;align-items:center;gap:10px;padding:0 14px;font-weight:500}.mess-ui-top-actions{display:flex;align-items:center;gap:12px}.mess-ui-month{height:36px;displ