imary{background:var(--primary);color:#fff}.mess-ui-btn-primary:hover{background:var(--primary-hover)}.mess-ui-btn-soft{background:var(--info-bg);color:var(--info-text);border-color:#DCEBFF}.mess-ui-btn-danger{background:var(--danger-bg);color:var(--danger-text);border-color:#FFD6D6}.mess-ui-btn-ghost{border-color:var(--soft-border)}.mess-ui-chip{display:inline-flex;align-items:center;justify-content:center;border-radius:999px;padding:5px 10px;font-size:12px;font-weight:700;white-space:nowrap}.mess-ui-chip-success{background:var(--success-bg);color:var(--success-text)}.mess-ui-chip-warning{background:var(--warning-bg);color:var(--warning-text)}.mess-ui-chip-danger{background:var(--danger-bg);color:var(--danger-text)}.mess-ui-chip-info{background:var(--info-bg);color:var(--info-text)}.mess-ui-toolbar{display:flex;align-items:center;justify-content:space-between;gap:14px;margin-bottom:14px}.mess-ui-filters{display:flex;gap:10px;flex-wrap:wrap}.mess-ui-input,.mess-ui-select,.mess-ui-textarea{height:42px;border:1px solid var(--soft-border);border-radius:12px;background:#fff;padding:0 12px;color:var(--text-main);font:inherit;outline:none}.mess-ui-input:focus,.mess-ui-select:focus,.mess-ui-textarea:focus{border-color:#9AC0FF;box-shadow:0 0 0 3px #EAF2FF}.mess-ui-textarea{height:94px;padding-top:10px;resize:vertical}.mess-ui-field{margin-bottom:14px}.mess-ui-field label{display:block;font-size:13px;color:#475569;font-weight:650;margin-bottom:7px}.mess-ui-table-wrap{background:#fff;border:1px solid var(--soft-border);border-radius:16px;overflow:auto;box-shadow:var(--shadow)}.mess-ui-table{width:100%;border-collapse:collapse;min-width:900px}.mess-ui-table th{height:42px;background:#FBFDFF;color:#64748B;text-align:left;font-size:12px;font-weight:750;padding:0 12px;border-bottom:1px solid var(--soft-border)}.mess-ui-table td{padding:12px;border-bottom:1px solid #F1F5FB;vertical-align:middle}.mess-ui-table tr:last-child td{border-bottom:0}.mess-ui-amount{text-align:right;font-variant-numeric:tabular-nums;font-weight:750}.mess-ui-member{display:flex;align-items:center;gap:10px}.mess-ui-mini-avatar{width:34px;height:34px;border-radius:11px;background:var(--info-bg);color:var(--info-text);display:grid;place-items:center;font-weight:800}.mess-ui-muted{color:var(--text-muted)}.mess-ui-checklist{display:grid;gap:10px}.mess-ui-check{display:flex;align-items:center;gap:10px;padding:10px 12px;border:1px solid var(--soft-border);border-radius:14px;background:#FBFDFF}.mess-ui-placeholder{height:190px;border:1px dashed #C8D7EA;border-radius:16px;background:linear-gradient(180deg,#FBFDFF,#F6F9FF);display:flex;align-items:center;justify-content:center;color:var(--text-muted);font-weight:650}.mess-ui-feed{display:grid;gap:12px}.mess-ui-feed-item{display:flex;gap:10px}.mess-ui-dot{width:8px;height:8px;border-radius:50%;background:var(--primary);margin-top:7px}.mess-ui-tabs{display:flex;gap:4px;border-bottom:1px solid var(--soft-border);margin-bottom:16px}.mess-ui-tab{padding:11px 14px;color:var(--text-muted);font-weight:700;border-bottom:3px solid transparent}.mess-ui-tab.is-active{color:var(--primary);border-color:var(--primary)}.mess-ui-profile-aside{display:grid;gap:16px}.mess-ui-profile-photo{width:86px;height:86px;border-radius:26px;background:var(--info-bg);color:var(--info-text);display:grid;place-items:center;font-size:32px;font-weight:800}.mess-ui-login-page{min-height:100vh;background:var(--app-bg);display:grid;place-items:center;padding:28px}.mess-ui-login-wrap{width:min(1040px,100%);display:grid;grid-template-columns:1fr 430px;gap:22px}.mess-ui-login-brand,.mess-ui-login-card{background:#fff;border:1px solid var(--soft-border);border-radius:24px;box-shadow:var(--shadow)}.mess-ui-login-brand{padding:38px;display:flex;flex-direction:column;justify-content:space-between;min-height:520px}.mess-ui-login-card{padding:32px}.mess-ui-badges{display:flex;gap:8px;flex-wrap:wrap;margin-top:22px}@media(max-width:1180px){.mess-ui-grid-4{grid-template-columns:repeat(2,minmax(0,1fr))}.mess-ui-grid-3{grid-template-columns:1fr 1fr}}@media(max-width:900px){.mess-ui-shell{grid-template-columns:1fr}.mess-ui-sidebar{position:relative;height:auto}.mess-ui-search{display:none}.mess-ui-content{padding:18px}.mess-ui-grid-4,.mess-ui-grid-3,.mess-ui-grid-2,.mess-ui-login-wrap{grid-template-columns:1fr}.mess-ui-login-brand{min-height:auto}.mess-ui-page-head,.mess-ui-toolbar{display:block}.mess-ui-row{margin-top:10px}}@media print{.mess-ui-sidebar,.mess-ui-topbar,.mess-ui-no-print{display:none!important}.mess-ui-shell{display:block}.mess-ui-content{padding:0}.mess-ui-card{box-shadow:none}}
